function flipChunks(s: string, k: number): string {
  const parts: string[] = [];
  for (let i = 0; i < s.length; i += 2 * k) {
    parts.push(s.slice(i, i + k).split("").reverse().join(""));
    parts.push(s.slice(i + k, i + 2 * k));
  }
  return parts.join("");
}

