function flipChunks(s: string, k: number): string {
  const a = s.split("");
  for (let i = 0; i < a.length; i += 2 * k) {
    let lo = i, hi = Math.min(i + k, a.length) - 1;
    while (lo < hi) {
      [a[lo], a[hi]] = [a[hi], a[lo]];
      lo++;
      hi--;
    }
  }
  return a.join("");
}

